def calculate_shipping_cost(weight_kg, distance_km, express):
    if weight_kg > 30:
        raise ValueError('Package exceeds maximum weight')
    base_rate = weight_kg * 2.75
    distance_surcharge = 0.0
    if distance_km > 500:
        distance_surcharge = distance_km * 0.012
    elif distance_km > 100:
        distance_surcharge = distance_km * 0.008
    if express:
        base_rate *= 1.85
    tax = (base_rate + distance_surcharge) * 0.07
    return round(base_rate + distance_surcharge + tax, 2)

def classify_bmi(weight_kg, height_m):
    if height_m <= 0:
        raise ValueError('Height must be positive')
    bmi = weight_kg / (height_m ** 2)
    if bmi < 18.5:
        category = 'Underweight'
    elif bmi < 25.0:
        category = 'Normal weight'
    elif bmi < 30.0:
        category = 'Overweight'
    else:
        category = 'Obese'
    return {'bmi': round(bmi, 1), 'category': category}

